// Thin wrapper around date-holidays. Each country's rules are a separate JSON chunk
// (generated by scripts/build-holiday-data.mjs) that is loaded on demand.
import type HolidaysParser from 'date-holidays-parser';
import countries from '../data/countries.json';
import type { ISODate } from './dates';

export interface Country {
  code: string;
  name: string;
}

export interface Holiday {
  date: ISODate;
  name: string;
}

export interface CountryHolidays {
  code: string;
  regions: { code: string; name: string }[];
  /** Public holidays (days off) for a year, sorted by date, one entry per name. */
  getHolidays(year: number, region?: string): Holiday[];
}

export const COUNTRIES: readonly Country[] = countries;
export const COUNTRY_CODES = new Set(COUNTRIES.map((c) => c.code));

/** Holiday types from date-holidays that are normally days off for everyone. */
const DAY_OFF_TYPES = new Set(['public', 'bank']);

const loaders = import.meta.glob<{ default: object }>('../data/holidays/*.json');
const cache = new Map<string, Promise<CountryHolidays>>();

export function loadCountry(code: string): Promise<CountryHolidays> {
  let p = cache.get(code);
  if (!p) {
    const load = loaders[`../data/holidays/${code}.json`];
    if (!load) return Promise.reject(new Error(`Unsupported country: ${code}`));
    // The holiday engine is a separate chunk so the page and form load without waiting for it.
    p = Promise.all([import('date-holidays-parser'), load()]).then(([engine, mod]) =>
      createCountry(engine.default, code, mod.default),
    );
    p.catch(() => cache.delete(code));
    cache.set(code, p);
  }
  return p;
}

function createCountry(Parser: typeof HolidaysParser, code: string, data: object): CountryHolidays {
  const base = new Parser(data, code, { languages: ['en'] });
  const states = base.getStates(code, 'en') ?? {};
  const regions = Object.entries(states)
    .map(([c, name]) => ({ code: c, name: String(name) }))
    .sort((a, b) => a.name.localeCompare(b.name));
  const parsers = new Map<string, HolidaysParser>([['', base]]);
  const years = new Map<string, Holiday[]>();

  return {
    code,
    regions,
    getHolidays(year, region = '') {
      const key = `${region}:${year}`;
      const cached = years.get(key);
      if (cached) return cached;
      let parser = parsers.get(region);
      if (!parser) {
        parser = new Parser(data, code, region, { languages: ['en'] });
        parsers.set(region, parser);
      }
      const seen = new Set<string>();
      const list: Holiday[] = [];
      for (const h of parser.getHolidays(year, 'en') || []) {
        if (!DAY_OFF_TYPES.has(h.type)) continue;
        // `date` is "YYYY-MM-DD hh:mm:ss" in the country's local time: keep the date part only.
        const date = h.date.slice(0, 10);
        const id = `${date}|${h.name}`;
        if (seen.has(id)) continue;
        seen.add(id);
        list.push({ date, name: h.name });
      }
      list.sort((a, b) => a.date.localeCompare(b.date));
      years.set(key, list);
      return list;
    },
  };
}

/** Guess a supported country from the browser's language tags (en-GB → GB). */
export function countryFromLocale(languages: readonly string[]): string | null {
  for (const tag of languages) {
    try {
      const region = new Intl.Locale(tag).maximize().region;
      if (region && COUNTRY_CODES.has(region)) return region;
    } catch {
      // ignore malformed tags
    }
  }
  return null;
}
